    name = "laplacian"

    def __init__(self, gamma=1.0):
        self.gamma = gamma

    def compute(self, X, Y):
        d = np.abs(X[:, None, :] - Y[None, :, :]).sum(-1)
        return np.exp(-self.gamma * d)
